style.css:
body {
  background-color: #f0f8ff; /* Fondo claro */
  font-family: Arial, Helvetica, sans-serif; /* Letra simple */
  margin: 20px;
}

/* Títulos principales */
h1 {
  color: #2c3e50; /* Azul oscuro */
  text-align: center; /* Centrado */
}

/* Párrafos */
p {
  color: #555; /* Gris */
  font-size: 16px;
  line-height: 1.5; /* Espaciado entre líneas */
}

/* Botones */
button {
  background-color: #3498db; /* Azul */
  color: white;
  padding: 10px 20px;
  border: none;
  cursor: pointer;
}

button:hover {
  background-color: #2980b9; /* Azul más oscuro al pasar el mouse */
}
